// Draws the application icon and the menu-bar icon from their SVG sources with Chromium (the Electron the app is built with), so what is drawn is exactly
// what a browser shows. Writes build/icon.png (1024 px), build/icon.icns (through macOS `iconutil`) and src/main/tray-icon.ts (18 pt template image).
// Only needed when an icon changes; the generated files are committed, so building the app does not run this.
// Usage: npm run make:icon   (runs `electron scripts/make-icon.mjs`)
import { Buffer } from 'node:buffer'
import { execFileSync } from 'node:child_process'
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { setTimeout as sleep } from 'node:timers/promises'
import { app, BrowserWindow } from 'electron'

const root = process.cwd()
const build = join(root, 'build')

/** The SVG at `size` px, as a PNG with a transparent background. */
async function render(window, svg, size) {
  window.setContentSize(size, size)
  const sized = svg.replace(/width="1024" height="1024"/, `width="${size}" height="${size}"`)
  const page = `<html><body style="margin:0;background:transparent;overflow:hidden">${sized}</body></html>`
  await window.loadURL(`data:text/html;base64,${Buffer.from(page).toString('base64')}`)
  await sleep(300)
  return (await window.webContents.capturePage({ x: 0, y: 0, width: size, height: size })).toPNG()
}

app.disableHardwareAcceleration()
app.whenReady().then(async () => {
  const window = new BrowserWindow({ width: 1024, height: 1024, show: false, useContentSize: true, transparent: true, backgroundColor: '#00000000', webPreferences: { offscreen: true } })
  try {
    const icon = readFileSync(join(build, 'icon.svg'), 'utf8')
    writeFileSync(join(build, 'icon.png'), await render(window, icon, 1024))
    const iconset = join(build, 'icon.iconset')
    rmSync(iconset, { recursive: true, force: true })
    mkdirSync(iconset)
    for (const size of [16, 32, 128, 256, 512]) {
      writeFileSync(join(iconset, `icon_${size}x${size}.png`), await render(window, icon, size))
      writeFileSync(join(iconset, `icon_${size}x${size}@2x.png`), await render(window, icon, size * 2))
    }
    try {
      execFileSync('iconutil', ['-c', 'icns', iconset, '-o', join(build, 'icon.icns')], { stdio: 'inherit' })
    } finally {
      rmSync(iconset, { recursive: true, force: true })
    }

    const tray = readFileSync(join(build, 'tray-icon.svg'), 'utf8')
    const one = (await render(window, tray, 18)).toString('base64')
    const two = (await render(window, tray, 36)).toString('base64')
    writeFileSync(
      join(root, 'src', 'main', 'tray-icon.ts'),
      '// GENERATED by scripts/make-icon.mjs from build/tray-icon.svg: do not edit by hand.\n' +
        '// The menu-bar icon: the star of the application icon in its orbit, black on transparent, as a macOS template image (18 pt, with a 36 px version for Retina).\n\n' +
        `export const TRAY_ICON_1X = '${one}'\n` +
        `export const TRAY_ICON_2X = '${two}'\n`
    )
    console.log('wrote build/icon.png, build/icon.icns and src/main/tray-icon.ts')
  } catch (error) {
    console.error(error)
    process.exitCode = 1
  } finally {
    app.quit()
  }
})
